package ama.transcript;
import java.util.*;import java.nio.file.*;import java.sql.*;import java.lang.reflect.*;import javax.sql.DataSource;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.core.env.*;import static org.junit.jupiter.api.Assertions.*;
/** SELECT-only CTE keys exercise the exact production builder without durable history seeding. */
class Task11Fix03KeysetSqlIT {
 final List<String> sqlTrace=new ArrayList<>();
 @Test void equalTimeUuidKeysetAndHistoryOverflowAreBoundedWithoutBusinessWrites()throws Exception {
  var source=guard(ama.publication.Task11Source.open());var j=new JdbcTemplate(source);String pub="12345678-1234-4234-8234-123456789abc",meeting="12345678-1234-4234-8234-123456789abd";var ids=List.of("12345678-1234-4234-8234-123456789a03","12345678-1234-4234-8234-123456789a02","12345678-1234-4234-8234-123456789a01","12345678-1234-4234-8234-123456789a04");var rows=new ArrayList<String>();for(int n=0;n<ids.size();n++)rows.add("SELECT '"+pub+"' publication_id,CAST('"+(n==3?"2026-10-25 11:59:59.999999":"2026-10-25 12:00:00.000000")+"' AS DATETIME(6)) created_at,CAST('"+ids.get(n)+"' AS CHAR(36) CHARACTER SET ascii) id");String cte="WITH publication_attempt AS ("+String.join(" UNION ALL ",rows)+") ";var observed=new ArrayList<String>();String cursor=null;var pages=new ArrayList<Map<String,Object>>();do{var key=PublicationHistoryCursor.decode("attempts",meeting,pub,cursor);var query=JdbcPublicationQueries.attemptPage(pub,key);var found=j.queryForList(cte+query.sql()+" LIMIT 2 FOR UPDATE",query.args().toArray());assertFalse(found.isEmpty());boolean more=found.size()>1;var row=found.getFirst();observed.add((String)row.get("id"));cursor=more?PublicationHistoryCursor.encode("attempts",meeting,pub,row):null;pages.add(Map.of("sql",query.sql()+" LIMIT 2 FOR UPDATE","args",query.args().stream().map(Object::toString).toList(),"id",row.get("id"),"hasMore",more));assertTrue(observed.size()<=4);}while(cursor!=null);assertEquals(ids,observed);assertEquals(4,new HashSet<>(observed).size());
  // Existing A has two genuine accepted submissions; cap1 must fail at count admission.
  String actualPub="adaed37b-2733-422a-af76-47853fadc771";var actual=j.queryForMap("SELECT p.meeting_id,m.owner_id FROM publication p JOIN meeting m ON m.id=p.meeting_id WHERE p.id=?",actualPub);assertTrue(j.queryForObject("SELECT COUNT(*) FROM publication_submission WHERE publication_id=?",Long.class,actualPub)>1);var propertiesClass=Class.forName("ama.api.Task11B1PublicReadsIT");var method=propertiesClass.getDeclaredMethod("properties");method.setAccessible(true);@SuppressWarnings("unchecked")var props=new HashMap<String,Object>((Map<String,Object>)method.invoke(null));props.put("minutes.bounds.tasks",1);var env=new StandardEnvironment();env.getPropertySources().addFirst(new MapPropertySource("fix03-overflow",props));var tx=new ama.db.TransactionRunner(source,10);var access=new ama.meeting.JdbcMeetingAccess(source,tx,new ama.task.JdbcSubjectFences(source,Set.of("MEETING")));var queries=new JdbcPublicationQueries(source,tx,access,env);int start=sqlTrace.size();var actor=new ama.contract.IdentityContracts.Actor((String)actual.get("owner_id"),ama.contract.IdentityContracts.Status.ACTIVE,Set.of(ama.contract.IdentityContracts.Role.USER));var failure=assertThrows(ama.contract.MinutesContracts.Failure.class,()->queries.history(actor,(String)actual.get("meeting_id"),actualPub,true,20,null));assertEquals(ama.contract.MinutesContracts.FailureCode.BUDGET_EXCEEDED,failure.code());var overflow=List.copyOf(sqlTrace.subList(start,sqlTrace.size()));assertTrue(overflow.stream().anyMatch(sql->sql.startsWith("SELECT COUNT(*)")&&sql.contains("publication_read_count")));assertFalse(overflow.stream().anyMatch(sql->sql.startsWith("SELECT task_id,publication_id,submission_no")&&sql.contains("FROM publication_submission")),"Count refusal must precede metadata transfer");
  Files.writeString(Path.of(System.getenv("AMA_TASK11_EVIDENCE_WINDOW"),"equal-time-and-overflow.json"),new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(Map.of("expected",ids,"actual",observed,"pages",pages,"overflowSql",overflow,"overflowCode",failure.code().name(),"dataOrigin","SELECT-only CTE values; no durable business rows seeded","existingActualOverflowPublication",actualPub,"mutations",0)));
 }
 DataSource guard(DataSource actual){return(DataSource)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{DataSource.class},(p,m,a)->{Object value=invoke(actual,m,a);if(!(value instanceof Connection c))return value;return Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{Object result=invoke(c,cm,ca);if(!(result instanceof PreparedStatement st)||ca==null||!(ca[0] instanceof String sql))return result;return Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{PreparedStatement.class},(sp,sm,sa)->{if(sm.getName().startsWith("execute")){assertTrue(sql.startsWith("SELECT ")||sql.startsWith("WITH "),"SELECT-only test");sqlTrace.add(sql);}return invoke(st,sm,sa);});});});}
 static Object invoke(Object target,Method method,Object[] args)throws Throwable{try{return method.invoke(target,args);}catch(InvocationTargetException error){throw error.getCause();}}
}
